SourceCode.Declaration:
/// <summary>
/// Custom-service wrappers over DataManagementDefinitionGroupEntity's static DMF actions, so the
/// app drives exports, status polls and upload URLs through HSMobileOpsServiceGroup instead of
/// the /data/ OData endpoint. Each method is a straight pass-through: same inputs, same result.
/// </summary>
class HSMobileOpsDmfService
{
}

Method.Source:
/// <summary>
/// Wraps DataManagementDefinitionGroupEntity::ExportToPackage. Returns the execution id.
/// </summary>
public HSMobileOpsDmfResponse exportToPackage(HSMobileOpsDmfRequest _request)
{
    HSMobileOpsDmfResponse response = new HSMobileOpsDmfResponse();
    response.parmValue(DataManagementDefinitionGroupEntity::ExportToPackage(
        _request.parmDefinitionGroupId(),
        _request.parmPackageName(),
        _request.parmExecutionId(),
        _request.parmReExecute(),
        _request.parmLegalEntityId()));
    return response;
}

/// <summary>
/// Returns the status symbol (Succeeded, Failed, Executing, ...).
/// </summary>
public HSMobileOpsDmfResponse getExecutionSummaryStatus(HSMobileOpsDmfRequest _request)
{
    HSMobileOpsDmfResponse response = new HSMobileOpsDmfResponse();
    DMFExecutionSummaryStatus status = DataManagementDefinitionGroupEntity::GetExecutionSummaryStatus(_request.parmExecutionId());
    response.parmValue(enum2Symbol(enumNum(DMFExecutionSummaryStatus), status));
    return response;
}

/// <summary>
/// Returns the download URL of a finished export.
/// </summary>
public HSMobileOpsDmfResponse getExportedPackageUrl(HSMobileOpsDmfRequest _request)
{
    HSMobileOpsDmfResponse response = new HSMobileOpsDmfResponse();
    response.parmValue(DataManagementDefinitionGroupEntity::GetExportedPackageUrl(_request.parmExecutionId()));
    return response;
}

/// <summary>
/// Returns the execution errors as the entity reports them (JSON text).
/// </summary>
public HSMobileOpsDmfResponse getExecutionErrors(HSMobileOpsDmfRequest _request)
{
    HSMobileOpsDmfResponse response = new HSMobileOpsDmfResponse();
    response.parmValue(DataManagementDefinitionGroupEntity::GetExecutionErrors(_request.parmExecutionId()));
    return response;
}

/// <summary>
/// Returns the writable blob JSON ({BlobId, BlobUrl}) for an upload.
/// </summary>
public HSMobileOpsDmfResponse getAzureWriteUrl(HSMobileOpsDmfRequest _request)
{
    HSMobileOpsDmfResponse response = new HSMobileOpsDmfResponse();
    response.parmValue(DataManagementDefinitionGroupEntity::GetAzureWriteUrl(_request.parmUniqueFileName()));
    return response;
}
